<script>
   /*************************************************************/
   /* AppPlots component for training app                       */
   /* -----------------------------------                       */
   /* defines plot components, controls and parameters          */
   /*************************************************************/

   import { untrack } from 'svelte';
   import { getDefaults } from 'svelte-controls-basic';
   import { Container, Button } from 'svelte-controls-basic';

   // global plot router
   import PlotsRouter from '@mdatools-apps/shared/plots/PlotsRouter.svelte';

   // import plot components
   import PlotScores from '@mdatools-apps/shared/plots/PlotScores.svelte';
   import PlotLoadings from '@mdatools-apps/shared/plots/PlotLoadings.svelte';
   import PlotBi from '@mdatools-apps/shared/plots/PlotBi.svelte';
   import PlotVariance from '@mdatools-apps/shared/plots/PlotVariance.svelte';
   import PlotEigenvalues from '@mdatools-apps/shared/plots/PlotEigenvalues.svelte';
   import PlotDistance from '@mdatools-apps/shared/plots/PlotDistance.svelte';

   // import plot controls components
   import { getPlotScoresControls, getPlotLoadingsControls, getPlotBiControls, getPlotVarianceControls,
            getPlotEigenvaluesControls, getPlotDistanceControls } from '@mdatools-apps/shared/plots/Controls.svelte.js';

   let {
      res,
      model,
      data,
      markOutlier,
      showContributions
   } = $props();

   // because most of the plot components expect JSON with results
   // assuming there is more than one result object we create it
   // same for the data

   // JSON with plot components (scope is needed for providing correct properties)
   const plots = $derived({
      scores: {label: 'Scores', scope: 'objects', component: PlotScores, buttons: buttons1},
      loadings: {label: 'Loadings', scope: 'stats', component: PlotLoadings},
      biplot: {label: 'Bi-plot', scope: 'stats', component: PlotBi},
      variance: {label: 'Variance', scope: 'stats', component: PlotVariance},
      eigenvals: {label: 'Eigenvalues', scope: 'stats', component: PlotEigenvalues},
      distance: {label: 'Distances', scope: 'objects', component: PlotDistance, buttons: buttons2},
   });

   // JSON with plots controls (as Widget properties). a plain object: the descriptors are never
   // changed after they are made, so there is nothing here for $state to track. untrack marks the
   // capture-at-mount as deliberate — AppContainer wraps this component in {#key s.calres}, so a
   // new set of results arrives as a new component and never as new props for this one
   const controls = untrack(() => ({
      scores: getPlotScoresControls(res),
      loadings: getPlotLoadingsControls(model),
      biplot: getPlotBiControls(res),
      variance: getPlotVarianceControls(res),
      eigenvals: getPlotEigenvaluesControls(),
      distance: getPlotDistanceControls(res)
   }));

   // the factory marks these two 'hidden', which is where they start and not something the data
   // rules out — nothing here makes them impossible, they simply wait for the right selection.
   // 'hidden' is OR-ed with the rule below and would keep them hidden for good, so it is cleared
   // and their visibility is left entirely to 'hiddenWhen'
   controls.scores.colorByVar.hidden = false;
   controls.scores.confEllipse.hidden = false;

   // which controls do not apply to what the user has currently selected. the factories above set
   // 'hidden' for what the data rules out, and Widget combines the two with OR, so a rule here can
   // never bring back a control the data has excluded
   controls.scores.comp1.hiddenWhen       = (p) => p.plotType !== 'p';
   controls.scores.showEllipse.hiddenWhen = (p) => p.plotType !== 'p';
   controls.scores.colorBy.hiddenWhen     = (p) => p.plotType === 'l' || p.plotType === 'b' || p.resID === 'both';
   controls.scores.colorByVar.hiddenWhen  = (p) => p.colorBy !== 'variable' || p.resID === 'both';
   controls.scores.confEllipse.hiddenWhen = (p) => !(p.colorBy === 'groups' && p.plotType === 'p') || p.resID === 'both';
   controls.loadings.comp1.hiddenWhen     = (p) => p.plotType !== 'p';

   // JSON with currently selected plots parameters
   let params = $state({
      scores: getDefaults(controls.scores),
      loadings: getDefaults(controls.loadings),
      biplot: getDefaults(controls.biplot),
      variance: getDefaults(controls.variance),
      eigenvals: getDefaults(controls.eigenvals),
      distance: getDefaults(controls.distance),
   });

   // parameters whose control has gone away are reset, because the plot reads them whatever is
   // shown: 'col1' is computed from 'colorBy' for every plot type, and 'getLim' widens the axes
   // from the stored ellipse ranges whenever 'showEllipse' or 'confEllipse' say so, neither of
   // them re-checking the plot type. the other hidden parameters are read behind the same
   // condition which hides them, so they can keep their value
   $effect(() => {
      const p = params.scores;
      if (controls.scores.showEllipse.hiddenWhen(p)) p.showEllipse = false;
      if (controls.scores.colorBy.hiddenWhen(p))     p.colorBy = 'none';
      if (controls.scores.confEllipse.hiddenWhen(p)) p.confEllipse = 'none';
   });

   // combine main elements to be shared with all plots together
   const props = $derived({res, model, data});


</script>

{#snippet buttons1(sel)}
   <Container label="Selected">
      <Button onclick={() => markOutlier(sel)} text="remove" class="destructive" />
   </Container>
{/snippet}

{#snippet buttons2(sel)}
   <Container label="Selected">
      <Button onclick={() => showContributions(sel, params.distance.ncomp)} text="plot" />
      <Button onclick={() => markOutlier(sel)} text="remove" class="destructive" />
   </Container>
{/snippet}


<PlotsRouter {plots} {controls} {props} bind:params={params} />